124	/// How one run is put in a container: what it mounts, what it hides, and
125	/// the volumes it keeps its login, sessions, and caches in.
126	#[derive(Clone, Debug, PartialEq)]
127	pub struct Plan {
128	    pub kind: RunKind,
129	    pub agent: Agent,
130	    pub project_dir: PathBuf,
131	    pub platform: Platform,
132	    /// What is mounted from the host, parents before what they hold.
133	    pub mounts: Vec<Mount>,
134	    /// Folders inside a mount that the run must not see, hidden behind an
135	    /// empty, read-only folder.
136	    pub hidden: Vec<PathBuf>,
137	}
138	
139	impl Plan {
140	    /// How a run of `kind` with `agent` in the project at `project_dir`,
141	    /// whose spec and code are at `locations`, is put in a container, with
142	    /// the task's understanding file, if it has one.
143	    pub fn new(
144	        kind: RunKind,
145	        agent: Agent,
146	        project_dir: &Path,
147	        locations: &Locations,
148	        understanding: Option<&Path>,
149	        platform: Platform,
150	    ) -> Self {
151	        let data = project_dir.join(APP_DIR);
152	        let reference = project_dir.join(agent.directory()).join("reference");
153	        let config = project_dir.join(crate::project_directory::CONFIG_FILE_NAME);
154	        let fluency = crate::piton_fluency::file(project_dir);
155	        let spec = locations.spec.clone();
156	        // A code location the config leaves out, or gives as the project
157	        // itself, is the whole project.
158	        let code = locations
159	            .code
160	            .clone()
161	            .unwrap_or_else(|| project_dir.to_path_buf());
162	        let rw = |host: PathBuf| Mount {
163	            host,
164	            writable: true,
165	        };
166	        let ro = |host: PathBuf| Mount {
167	            host,
168	            writable: false,
169	        };
170	        let mut mounts = Vec::new();
171	        match kind {
172	            RunKind::Spec => {
173	                mounts.extend(spec.clone().map(rw));
174	                mounts.push(rw(reference));
175	                mounts.push(ro(fluency));
176	                mounts.push(ro(config));
177	                mounts.extend(understanding.map(|file| rw(file.to_path_buf())));
178	            }
179	            RunKind::Question => {
180	                mounts.push(ro(code.clone()));
181	                mounts.push(ro(reference));
182	                mounts.push(ro(config));
183	            }
184	            RunKind::Code => {
185	                mounts.push(rw(code.clone()));
186	                mounts.push(ro(reference));
187	                mounts.push(ro(config));
188	                mounts.extend(understanding.map(|file| rw(file.to_path_buf())));
189	            }
190	        }
191	        // What a mount holds that the run must not see: the other location,
192	        // the project's data, and its git directory.
193	        let mut unseen = vec![data, project_dir.join(".git")];
194	        match kind {
195	            RunKind::Spec => unseen.push(code),
196	            RunKind::Question | RunKind::Code => unseen.extend(spec),
197	        }
198	        let hidden = unseen
199	            .into_iter()
200	            .filter(|unseen| {
201	                mounts
202	                    .iter()
203	                    .any(|mount| unseen.starts_with(&mount.host) && *unseen != mount.host)
204	            })
205	            .collect();
206	        // Parents first, so what they hold is mounted over them.
207	        mounts.sort_by_key(|mount| mount.host.components().count());
208	        Self {
209	            kind,
210	            agent,
211	            project_dir: project_dir.to_path_buf(),
212	            platform,
213	            mounts,
214	            hidden,
215	        }
216	    }
217	
218	    /// This plan as the host stands: a folder it writes to that isn't there
219	    /// yet made, as the compiled reference before the first build, and
220	    /// anything else that isn't there left out, as the fluency file before
221	    /// it is written, since only what is there can be mounted.
222	    pub fn as_on_host(&self) -> Self {
223	        let mut plan = self.clone();
224	        plan.mounts.retain(|mount| {
225	            if !mount.host.exists() && mount.writable && mount.host.extension().is_none() {
226	                std::fs::create_dir_all(&mount.host).ok();
227	            }
228	            mount.host.exists()
229	        });
230	        plan.hidden.retain(|hidden| hidden.exists());
231	        plan
232	    }
