234	    /// Where the host path `host` is in the container: the same path where
235	    /// the platform allows, and otherwise under the workspace, from the
236	    /// project directory.
237	    pub fn container_path(&self, host: &Path) -> PathBuf {
238	        if self.platform.same_paths() {
239	            return host.to_path_buf();
240	        }
241	        let within = host.strip_prefix(&self.project_dir).unwrap_or(host);
242	        let mut path = PathBuf::from(WORKSPACE);
243	        for part in within.components() {
244	            path.push(part.as_os_str());
245	        }
246	        path
247	    }
248	
249	    /// The host path of `path`, a path the run reported from its container;
250	    /// none when it is nowhere on the host.
251	    #[cfg(test)]
252	    pub fn to_host(&self, path: &Path) -> Option<PathBuf> {
253	        if self.platform.same_paths() {
254	            return Some(path.to_path_buf());
255	        }
256	        let within = path.strip_prefix(WORKSPACE).ok()?;
257	        Some(self.project_dir.join(within))
258	    }
259	
260	    /// A line the run printed, every path in it from its container mapped
261	    /// back to the host, so whatever reads it sees host paths.
262	    pub fn map_line(&self, line: &str) -> String {
263	        if self.platform.same_paths() {
264	            return line.to_string();
265	        }
266	        // JSON escapes a Windows path's separators.
267	        let host = self.project_dir.to_string_lossy().replace('\\', "\\\\");
268	        line.replace(WORKSPACE, &host)
269	    }
270	
271	    /// The volume holding the harness's sessions for this run's
272	    /// conversation in its project.
273	    pub fn session_volume(&self) -> String {
274	        session_volume(&self.project_dir, self.kind)
275	    }
276	
277	    /// The arguments to `podman` that run `command` with `args` in a
278	    /// container of `image` as this plan says, its input open; with `tty`,
279	    /// under a terminal of its own.
280	    pub fn run_args(
281	        &self,
282	        image: &str,
283	        command: &str,
284	        args: &[OsString],
285	        tty: bool,
286	    ) -> Vec<OsString> {
287	        let mut out: Vec<OsString> = vec!["run".into(), "--rm".into(), "-i".into()];
288	        if tty {
289	            out.push("-t".into());
290	        }
291	        // Files it writes belong to the user, as on the host.
292	        if self.platform == Platform::Linux {
293	            out.push("--userns=keep-id".into());
294	        }
295	        out.extend(["--label".into(), "suspense=run".into()]);
296	        out.extend(["-e".into(), format!("HOME={HOME}").into()]);
297	        // The harness's login and settings, shared by every project, and the
298	        // sessions of this conversation in this project over them.
299	        out.extend([
300	            "-v".into(),
301	            format!("{}:{HOME}:U", home_volume(self.agent)).into(),
302	        ]);
303	        out.extend([
304	            "-v".into(),
305	            format!(
306	                "{}:{HOME}/{}:U",
307	                self.session_volume(),
308	                session_dir(self.agent)
309	            )
310	            .into(),
311	        ]);
312	        if self.kind == RunKind::Code {
313	            out.extend([
314	                "-v".into(),
315	                format!("{}:{CACHE}:U", cache_volume(&self.project_dir)).into(),
316	            ]);
317	            out.extend(["-e".into(), format!("CARGO_HOME={CACHE}/cargo").into()]);
318	            out.extend([
319	                "-e".into(),
320	                format!("CARGO_TARGET_DIR={CACHE}/target").into(),
321	            ]);
322	        }
323	        for mount in &self.mounts {
324	            let mut spec: OsString = "type=bind,src=".into();
325	            spec.push(mount.host.as_os_str());
326	            spec.push(",dst=");
327	            spec.push(self.container_path(&mount.host).as_os_str());
328	            if !mount.writable {
329	                spec.push(",ro=true");
330	            }
331	            out.extend(["--mount".into(), spec]);
332	        }
333	        for hidden in &self.hidden {
334	            let mut spec: OsString = "type=tmpfs,dst=".into();
335	            spec.push(self.container_path(hidden).as_os_str());
336	            spec.push(",ro=true");
337	            out.extend(["--mount".into(), spec]);
338	        }
339	        out.push("-w".into());
340	        out.push(self.container_path(&self.project_dir).into_os_string());
341	        out.push(image.into());
342	        out.push(command.into());
343	        out.extend(args.iter().cloned());
344	        out
345	    }
346	}
