368	/// Where, under its home, a harness keeps its sessions.
369	fn session_dir(agent: Agent) -> &'static str {
370	    match agent {
371	        Agent::Claude => ".claude/projects",
372	        Agent::Codex => ".codex/sessions",
373	        Agent::OpenCode => ".local/share/opencode/storage",
374	    }
375	}
