377	/// A short, stable name for the project at `project_dir`.
378	fn project_key(project_dir: &Path) -> String {
379	    let name = project_dir
380	        .file_name()
381	        .map(|name| name.to_string_lossy().to_lowercase())
382	        .unwrap_or_default()
383	        .chars()
384	        .filter(|c| c.is_ascii_alphanumeric() || *c == '-')
385	        .take(24)
386	        .collect::<String>();
387	    format!("{name}-{}", short_hash(&project_dir.to_string_lossy()))
388	}
389	
390	fn short_hash(text: &str) -> String {
391	    let mut hasher = DefaultHasher::new();
392	    text.hash(&mut hasher);
393	    format!("{:012x}", hasher.finish() & 0xffff_ffff_ffff)
394	}
